INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,url_slug,status,updated_at,created_at) VALUES
('pipe-maze','Pipe Maze','minion','legitch',NULL,'','SCP Fragmented Veil','{"slug":"pipe-maze","name":"Pipe Maze","team":"minion","ability":"If a player is executed, it''s redirected to another based on a rule (you start knowing it), if it can (unless it ends the game).","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Pipe Maze (SCP-015) is a sentient labyrinth of pipes with a mindless primitive goal to expand and conquer. The pipes also act as a network to disperse hazards and travesties.","summaryBullets":["The Pipe Maze starts with a rule. The rule can be of any length, but is typically a sentence long.","Whenever a player is executed, if the rule has a valid target, it will redirect that execution & kill to the end-point target.","Even if the originally executee could survive that execution, the execution and kill will process the new target, and disregard the previous one.","If the new execution would then result in the immediate end of the game {{i|(such as killing the Demon or the Saint)}}, it is simply not processed and the ability doesn''t activate for it."],"howToRun":["During setup, write the Pipe Maze''s rule on a piece of paper, or on a phone.","During the first night, wake the Pipe Maze. Show this rule, then put them to sleep.","If a player is executed, instead, another non-Demon player will be executed based on the Pipe Maze''s rule, if applicable."],"tips":["Try to keep your Pipe Maze rules into a single sentence so that it is easier to keep track and manage for a good team dealing with it. It is the power of execution re-direction after-all."],"quote":"You will die here... this place will be your grave. You will be contained here forever... and I will live...","iconBy":"le_nuberto","jinxes":[{"name":"Evil Twin","align":"evil","text":"The Pipe Maze''s ability cannot redirect an execution onto or away from the evil twin.","id":"eviltwin"},{"name":"Mastermind","align":"evil","text":"If the Mastermind is alive & activated their ability, the Pipe Maze loses theirs.","id":"mastermind"},{"name":"Matsuraid","align":"evil","text":"Only 1 jinxed character can be in play.","id":"matsuraid_hblreleased"},{"name":"Steeplejack","align":"good","text":"If the Steeplejack dies at night & chooses the Pipemaze, they may visit the Storyteller tomorrow to learn a hint towards the the Pipemaze''s rule. If not in play, this info is arbitrary.","id":"steeplejack_the_bootleggers_anthology"},{"name":"Heir","align":"evil","text":"Players that die in someone''s stead register as being executed to the Pipe Maze.","id":"heir_darkartists_stuff"}],"customBoxes":[{"title":"Alternative JSON (Older)","content":"If you feel like the Pipe Maze should only be able to die to execution *(extending to their own ability)* on a script where evil players might be able to die at night, use this JSON.\n\nIf the Pipe Maze would die, they remain alive, but they die if they are drunk, poisoned, or executed.\n\n**Pipe Maze █+** (Minion)\nWhen a player is executed, it''s redirected to another non-Demon player based on a rule (you start knowing it), if it can. You can only die by execution.\n\n**First night:** Show the Pipe Maze their rule.\n**Credit:** Ability: @legitch. Image: @le_nuberto\n\n**Jinxes:**\nFearmonger: The Pipe Maze''s ability cannot redirect an execution onto or away from the Fearmonger''s target.\nEvil Twin: The Pipe Maze''s ability cannot redirect an execution onto or away from the good or evil twin.\nLleech: The Pipe Maze''s ability cannot redirect an execution onto or away from the Lleech host.\nMastermind: If the Mastermind is alive & activated their ability, the Pipe Maze loses theirs.\nSaint: The Pipe Maze''s ability cannot redirect an execution onto or away from the Saint.\nPossessre: The Pipe Maze''s ability cannot redirect an execution onto or away from the last Possessre target.\nMatsuraid: Only 1 jinxed character can be in play.\nSteeplejack: If the Steeplejack dies at night & chooses the Pipemaze, they may visit the Storyteller tomorrow to learn a hint towards the the Pipemaze''s rule. If not in play, this info is arbitrary.\nHeir: Players that die in someone''s stead register as being executed to the Pipe Maze."}],"firstNight":11.015,"otherNight":0,"setup":false,"firstNightReminder":"Show the Pipe Maze their rule.","art":"art/pipe-maze.png","jsonId":"pipemaze_scp_fragmented_veil","curata":false}','scp-fragmented-veil/pipe-maze','published',datetime('now'),datetime('now')),
('missing-no','Missing No.','minion','legitch',NULL,'','SCP Fragmented Veil','{"slug":"missing-no","name":"Missing No.","team":"minion","ability":"Marked abilities register falsely & yield false info (except choosing). You & the Demon are safe from marked non-Demon abilities.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Missing No. (SCP-033) is a mathematically forgotten number that disrupts the space of reality on whatever it is transcribed on.","summaryBullets":["Yes is no and no is yes in the chaotic world thrown in by the Missing No.","With the Missing No. in-play, abilities must register other players falsely, whilst simultaneously not being able to provide true info.","Minions become not Minions, good becomes evil, vice-versa, and etc.","Whilst any marked ability must yield false info different from what the user would truly learn, they only learn something false if the mis-registering of players would not affect the final result of the yielded info.","However, when marked players are other players with their ability, they are still prompted to choose exclusively they players they would normally be able to pick.","Nonetheless, this character''s text is up to interpretation by the Storyteller, and may be subject to different iterations of being run based on intention and design. As always, if there is any confusion, the Storyteller should clarify any misunderstandings they may have set.","Lastly, both the Missing No. are and the Demon are safe from said marked abilities at all times - they cannot be drunkened, poisoned, killed at night, lose their ability, or otherwise be subjected to any negative effect.","This excludes the Demon''s abilities, and Fabled abilities {{i|(dependant on which Fabled and depending on how the Storyteller wants to run the game)}}"],"howToRun":["On the script, place a mark on characters whose abilities you want to be susceptible to the Missing. No''s corruption.","While preparing the first night, put the Missing No.''s **SAFE** reminder token by the Missing No. and the Demon.","The Missing No''s protection prevents all harmful effects of marked abilities, such as death, poisoning, losing your ability, or being transformed into a weaker character.","Each time a player is targeted by a marked player''s ability that detects or affects specific characters or players, choose which character, alignment, state, and or player that player registers as. Do whatever is appropriate, such as showing an good or evil character token, nodding, giving finger signals, or allowing an ability to work that would normally only affect good, evil, Townsfolk, Outsider, Minion, or Demon players. However, if the then yielded info from this operation is still true when the marked ability prompts you to give information, you must give false information instead."],"tips":["Feel free to still mark characters with the Missing No. based off your interpretation of how exactly ''register falsely'' works. If there is any confusion regarding how the Missing No. disrupts an ability, whether you hear it in a private conversation or get publicly asked, feel free to clarify your interpretation of how the Missing No. works with a marked character."],"quote":"Every school child knows that 2 plus 2 is 4. The solid mathematical certainty of numerical order and value is the basis for all logic-based systems. We know that after 2 comes 3 and after 3 comes 4. What this formula proves is that we missed a number somewhere. Imagine if all our technology was based on the belief that after 4 came 6. We simply didn''t know or conceive of 5. That is, in essence, what this formula proves—we missed a number. -Physics & Mathematical Scientist Prof. Hutchinson","iconBy":"le_nuberto","customBoxes":[{"title":"Alternative JSON & How to Run (Older)","content":"If you want to use the older version of the Missing No., where it categorically disrupted information at an immensely wide scale, use this JSON.\n\nEach night, wake the Missing No.. They show any information feedback/signal (finger signals, characters on the script, other players, head nods, thumbs up or down, and any other type of ability target, or a combination of any). Give a thumbs up to acknowledge their choice and put them to sleep. Write down that information on a piece of paper, or on a phone.\n\nWhen a Townsfolk or Outsider would get that information with their ability, they instead get another piece of information regardless of it''s authenticity that''s valid for their ability. If there is no non-blacklisted information the ability can yield, the blacklist will not be applied for that instance.\n\n**Missing No. █~** (Minion)\nEach night, choose a piece of information feedback: Townsfolk & Outsiders that would learn it will learn something else instead if they can.\n\n**First night:** The Missing No. shows information feedback/signals. Townsfolk and Outsiders that would get this information from their ability will instead get another piece of information of the same type, if it''s valid for their ability.\n**Other nights:** The Missing No. shows information feedback/signals. Townsfolk and Outsiders that would get this information from their ability will instead get another piece of information of the same type, if it''s valid for their ability.\n**Credit:** Ability: @legitch. Image: @le_nuberto"}],"firstNight":0,"otherNight":0,"reminders":["Safe","Safe"],"setup":true,"art":"art/missing-no.png","jsonId":"missingno_scp_fragmented_veil","curata":false}','scp-fragmented-veil/missing-no','published',datetime('now'),datetime('now')),
('unknown','[unknown]','minion','legitch',NULL,'','SCP Fragmented Veil','{"slug":"unknown","name":"[unknown]","team":"minion","ability":"Each night, choose a player (different from last night): they (until dusk) & you might register as nothing to player abilities.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The [unknown] (SCP-055) is an unknown thing that cannot remembered by anyone in any medium, causing detrimental effects to anyone who obtains information about it.","summaryBullets":["Whenever the [unknown] or their target would be detected by a player''s ability, the Storyteller may choose whether they are, or aren''t.","In short, ''Voided'' players {{i|(those chosen by the [unknown] and the [unknown] themselves)}} might not register as anything when an ability is faced with a condition - they are ''not'' what the ability is asking for.","Additionally, ''Voided'' players might also not register as alive, or even as another player, thus potentially not being affected by any player''s ability at all.","However, whilst ''Voided'' players might not have effects passed on to them, information yielded from them must still occur.","Lastly, ''Voided'' players however as still subject and vulnerable to the rules of the game, such as by nominations & executions, as-well as Fabled characters."],"howToRun":["Each night, wake the [unknown]. They point at any player. That player becomes voided—put the **NULL & VOID** reminder token by the chosen player''s character token. Put the [unknown] to sleep.","The [unknown] and the voided player wakes and acts normally as they cannot register as nothing outside of player abilities. Each time the [unknown] or the voided player is targeted by an ability that detects or affects specific characters or player types, choose which state that player registers as in the moment. You may even choose to not make them register as a player at all, allowing them to be completely unaffected by the ability targeting them. Note that this does not work against information abilities that show something based on the target players, whilst it does work on information abilities that do show something different from their standard output based on the target players.","Each dusk, the voided player is no longer affected - remove their **NULL & VOID** reminder."],"examples":["The Empath is neighbouring an evil player chosen by the [unknown]. That night, the Empath''s ability mis-registers them as **not** evil, and the Empath learns a false number.","The Demon is currently chosen by the [unknown], and kills the Sage. They register as **not** the Demon, and the Sage doesn''t wake that night.","The Sailor uses their ability on the [unknown]. The Storyteller decides that the [unknown] does not register as a player in this instance, and is not drunk, whilst the Sailor is not drunk either.","The only Village Idiot chooses the [unknown]. As information yielded from them still occurs and there is no way the [unknown] could mis-register as **not** an alignment, the Village Idiot learns true information that night."],"tips":["You should let ''Voided'' players will have their nullification trigger as much as possible once the first night is prepared and after the evil team''s info step occurs - much more than how a Spy or Recluse''s mis-registration would occur. I mean, that is the [unknown]''s ability, let them shine with it! {{i|(provided it isn''t grossly overdominating the good team into submission)}}"],"quote":"i forgor 💀","iconBy":"le_nuberto","jinxes":[{"name":"Plague Doctor","align":"good","text":"If the Plague Doctor dies, a living Minion gains the [unknown]''s ability in addition to their own ability, and learns this.","id":"plaguedoctor"}],"customBoxes":[{"title":"Alternative JSON","content":"For if you want an easier [unknown] that doesn''t perform its misregistration alteration on itself, use this JSON.\n\n**[unknown] █-** (Minion)\nEach night, choose a player (different from last night): they might register as nothing to player abilities until dusk.\n\n**First night:** The [unknown] points to a player. That player is voided and might not register as nothing to other player''s abilities.\n**Other nights:** The previously voided player is no longer voided. The [unknown] points to a player. That player is voided and might not register as nothing to other player''s abilities.\n**Reminders:** Null & Void\n**Credit:** Ability: @legitch. Image: @le_nuberto"}],"firstNight":0.055,"otherNight":0.055,"reminders":["Null & Void"],"setup":false,"firstNightReminder":"The [unknown] points to a player. That player is voided and might not register as nothing to other player''s abilities.","otherNightReminder":"The previously voided player is no longer voided. The [unknown] points to a player. That player is voided and might not register as nothing to other player''s abilities.","art":"art/unknown.png","jsonId":"unknown_scp_fragmented_veil","curata":false}','scp-fragmented-veil/unknown','published',datetime('now'),datetime('now')),
('infernal','Infernal','minion','legitch',NULL,'','SCP Fragmented Veil','{"slug":"infernal","name":"Infernal","team":"minion","ability":"For each non-Townsfolk teammate (or yourself) that died since last night, choose a player tonight: they die the next night.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Infernal (SCP-060) is a grove of oak trees that, when burned, summons a skeletal defender to aggressively attack anyone within it''s vicinity.","summaryBullets":["The Infernal avenges their teammates by selecting targets to burn and then die the next night.","Teammates that are not Townsfolk will not counted for this ability in the unique cases that the Infernal is good or there are evil Townsfolk.","The Infernal will avenge themselves should they die, but will not avenge anymore players from beyond the grave."],"howToRun":["If the Infernal or a non-Townsfolk teammate of the Infernal dies, mark them with the **VENGEANCE** reminder token. If it was the Infernal, remove all other **VENGEANCE** reminder tokens {{i|(they will only avenge themselves)}}.","Each night except the first, each player marked with the Infernal''s **DIES TOMORROW** reminder token {{i|dies}} - replace those reminder(s) with the **DEAD** reminder token(s). If any players are marked with the **VENGEANCE** reminder token, wake the Infernal. Show fingers equalling the number of characters with the **VENGEANCE** reminder token, they point at that many players. Remove the **VENGEANCE** reminder tokens and put the Infernal to sleep. The chosen player {{i|dies the next night}} - mark them with the **DIES TOMORROW** reminder."],"quote":"Pay what you owe... pay what you owe... pay what you owe...","iconBy":"le_nuberto","jinxes":[{"name":"Plague Doctor","align":"good","text":"The evil team registers as the Storyteller''s team if they have the Infernal ability.","id":"plaguedoctor"}],"customBoxes":[{"title":"Alternative JSON & How to Run (Older)","content":"For if you want the older version of the Infernal that instead only caused mis-registering, use this JSON.\n\nIf the Infernal or a non-Townsfolk teammate of the Infernal dies, mark them with the VENGEANCE reminder token. If it was the Infernal, remove all other VENGEANCE reminder tokens (they will only avenge themselves).\n\nEach night except the first, if any players are marked with the VENGEANCE reminder token, wake the Infernal. Show fingers equalling the number of characters with the VENGEANCE reminder token, they point at that many players. Remove the VENGEANCE reminder tokens and put the Infernal to sleep. The chosen player might register as evil from now on - mark them with the RECLUSIVE reminder. If the Infernal dies, remove all RECLUSIVE reminder tokens, but not the one they''ll be inflicting tonight by avenging their own death.\n\n**Infernal █~** (Minion)\nFor each non-Townsfolk teammate (or yourself) that died since last night, choose a player tonight: they might register as evil & an evil character.\n\n**Other nights:** For each non-Townsfolk teammate that died since you last woke: the Infernal points to a player. That player might register as evil from now on.\n**Reminders:** Vengeance, Vengeance, Reclusive, Reclusive, Reclusive, Reclusive\n**Credit:** Ability: @legitch. Image: @le_nuberto\n\n**Jinxes:**\nPlague Doctor: The evil team registers as the Storyteller''s team if they have the Infernal ability."}],"firstNight":0,"otherNight":52.06,"reminders":["Vengeance","Vengeance","Dies tomorrow","Dies tomorrow","Dead","Dead"],"setup":false,"otherNightReminder":"The previously chosen player dies. For each non-Townsfolk teammate that died since you last woke: the Infernal points to a player. That player dies the next night.","art":"art/infernal.png","jsonId":"infernal_scp_fragmented_veil","curata":false}','scp-fragmented-veil/infernal','published',datetime('now'),datetime('now'));
